import re,json
s=open('auto.txt').read()
# each merge: a space-separated run in auto -> joined (spaces dropped inside), applied to all occurrences (token-bounded)
M='''ཕ་ ཝད་|བུམ་ པ་|བདུད་ རྩི་|སྡིག་ པའི་|ཟླ་ བ་|དབྱུག་ ཐོ་|རྣལ་ འབྱོར་|དམར་ ལྗང་|ཁོག་ ཆེན་|སྟོབས་ ཆེན་|གཅོད་ པ་|འདོད་ པ་|པུ་ ཤུད་|ནོར་ སྲུང་|ཤ་ བའི་|རླུང་ ལྷ་|བ་ དན་|འཕྱར་ བ་|མི་ མོ་|གསལ་ ཤིང་|ཕག་ མོ་|མཆེ་ ཞགས་|ཁྭ་ ཏའི་|ཞིང་ ཆུང་|སྣ་ ཆེན་|ཆུ་ ལྷ་|སྦྲུལ་ ཞགས་|ཁུ་ བྱུག་|སྟོང་ པའི་|ཁྲོ་ བའི་|ལྷ་ རུ་|རང་ཤར་ བར་|སངས་རྒྱས་ པའོ༔|བྲེད་ པས་|སྣོན་ མར་|འགྲོ་ གོ།|གཤིན་ རྗེ་|བརྒྱལ་ ལོ༔|བདུད་ དུ་|འཁྱམས་ སོ༔|མཉམ་ པ༔|རི་ རབ་|བཅོ་ བརྒྱད་|བརྩེགས་ པ་|སྣང་ སྲིད་|སངས་རྒྱས་ སོ༔|མཐོང་ སྣང་|སངས་རྒྱས་ པ་|རྫོགས་ སངས་རྒྱས་|སང་ རེས་|མགོན་ པོ་|ནག་ པོའི་|ཆོས་ ཀྱི་ རྒྱལ་ པོའི་|བསྐལ་ བར་|འབྲིང་ པོ་|ཡོང་ ངོ༔|ཡ་ སོས་|མ་ མཆུ་|མནན་ པ༔|མིག་ ཤེལ་|མིག་ ཏུ་|སྤྱི་ བོར་|བཅིངས་ པ༔|གསུས་ པ་|ཕྲ་ བ༔|ཁྲམ་ ཤིང་|རྒྱོབ་ སོད་|ཀླད་ པ་|འཐུང་ བ༔|ཕྲལ་ བ༔|དོན་ སྙིང་|འདོན་ པ༔|དེ་ ལྟ་བུའི་|བྱུང་ བའི་|བསད་ པ་|བཏུབས་ པ་|སྟོང་ ཉིད་|རང་ གཟུགས་|དངོས་པོ་ ཅན་ དུ་|སྟོང་པ་ ཉིད་|རྙེད་ དོ༔|མ་ གཏོགས༔|ཕྱི་ རོལ་དུ་|འཇིགས་ འཇིགས་|དངོས་ སུ་|ཐག་ ཆོད་ དོ༔|ཐག་ ཆོད་|རང་ སར་|འབྱོན་ པར་|འདུག་ གོ༔|རྗེས་ སུ་|བོས་ ཅིག༔|ར་ མདའ་|རྒྱུག་ ཅིག༔|བཟུང་ ཞིག༔|ཡོད་པ༔|མ་ ཐག་|གཤིན་རྗེ་ རུ་'''.split('|')
toks=s.split(' ')
for m in M:
    parts=m.split(' ')
    n=len(parts); out=[]; i=0; hit=0
    while i<len(toks):
        if toks[i:i+n]==parts:
            out.append(''.join(parts)); i+=n; hit+=1
        else: out.append(toks[i]); i+=1
    if not hit and m!='ཡོད་པ༔': print('NO HIT',m)
    toks=out
# splits: ཁྲག་འཐུང་ བ་ (verb) -> ཁྲག་ འཐུང་བ་
out=[];i=0
while i<len(toks):
    if toks[i]=='ཁྲག་འཐུང་' and i+1<len(toks) and toks[i+1]=='བ་':
        out+= ['ཁྲག་','འཐུང་བ་']; i+=2
    else: out.append(toks[i]); i+=1
toks=out
assert ''.join(toks)==open('fixed.txt').read()
json.dump(toks,open('toks.json','w'),ensure_ascii=False)
for i,t in enumerate(toks): print(i,t,end='  ')
